51016-B-9","room_id":79,"room_number":3,"name":"Прихожая","source_image":"/layouts/block_b/catalog/block_b_typical_type_09_54_58m2_3d.png","old_x":50,"old_y":50,"x":56,"y":71},{"layout_id":17,"layout_code":"PDF20251016-B-9","room_id":80,"room_number":4,"name":"Ванная","source_image":"/layouts/block_b/catalog/block_b_typical_type_09_54_58m2_3d.png","old_x":50,"old_y":50,"x":20,"y":71}]$data$::jsonb;
begin
 perform 1 from public.layout_rooms where id in (select (v->>'room_id')::integer from jsonb_array_elements(payload) v) for update;
 if (select count(*) from jsonb_to_recordset(payload) as p(layout_id integer,layout_code text,room_id integer,room_number integer,old_x numeric,old_y numeric,x numeric,y numeric)
 join public.layout_rooms r on r.id=p.room_id and r.layout_type_id=p.layout_id and r.room_number=p.room_number
 join public.layout_types l on l.id=r.layout_type_id and l.project_id=3 and l.code=p.layout_code
 where (r.position_x_percent=p.old_x and r.position_y_percent=p.old_y) or (r.position_x_percent=p.x and r.position_y_percent=p.y)) <> 77
 then raise exception 'Marker source changed; review coordinates before applying'; end if;
 update public.layout_rooms r set position_x_percent=p.x,position_y_percent=p.y,updated_at=now()::text
 from jsonb_to_recordset(payload) as p(layout_id integer,room_id integer,x numeric,y numeric)
 where r.id=p.room_id and r.layout_type_id=p.layout_id and (r.position_x_percent is distinct from p.x or r.position_y_percent is distinct from p.y);
end; $fix$;
commit;

